sys_script_include.script:
var FineAmountLookupAjax = Class.create();
FineAmountLookupAjax.prototype = Object.extendsObject(global.AbstractAjaxProcessor, {

    getFineAmount: function() {
        var violationSysId = this.getParameter('sysparm_violation_id');
        if (!violationSysId) {
            return '';
        }

        var violationGr = new GlideRecord('violation_type'); 
        if (violationGr.get(violationSysId)) {
            return violationGr.getValue('fine_amount'); 
        }

        return '';
    },

    type: 'FineAmountLookupAjax'
});
